**Refactored Code:**

```python
# order_service.py
from dataclasses import dataclass
from abc import ABC, abstractmethod
from typing import Optional

@dataclass
class OrderResult:
    success: bool
    order_id: Optional[str] = None
    total: Optional[float] = None
    error: Optional[str] = None

class UserRepository(ABC):
    @abstractmethod
    def get_user(self, user_id: str) -> Optional[dict]:
        pass

class OrderRepository(ABC):
    @abstractmethod
    def save_order(self, order_data: dict, total: float) -> str:
        pass

class EmailService(ABC):
    @abstractmethod
    def send_confirmation(self, email: str, order_id: str) -> None:
        pass

class OrderService:
    def __init__(
        self,
        user_repo: UserRepository,
        order_repo: OrderRepository,
        email_service: EmailService
    ):
        self.user_repo = user_repo
        self.order_repo = order_repo
        self.email_service = email_service

    def validate_order(self, order_data: dict) -> Optional[str]:
        if not order_data.get('user_id'):
            return 'Missing user_id'
        if not order_data.get('items'):
            return 'Missing items'
        for item in order_data['items']:
            if 'price' not in item or 'quantity' not in item:
                return 'Invalid item format'
        return None

    def calculate_total(self, items: list, is_premium: bool) -> float:
        total = sum(item['price'] * item['quantity'] for item in items)
        if is_premium:
            total *= 0.9
        return total

    def process_order(self, order_data: dict) -> OrderResult:
        error = self.validate_order(order_data)
        if error:
            return OrderResult(success=False, error=error)

        user = self.user_repo.get_user(order_data['user_id'])
        if not user:
            return OrderResult(success=False, error='User not found')

        is_premium = user.get('is_premium', False)
        total = self.calculate_total(order_data['items'], is_premium)

        order_id = self.order_repo.save_order(order_data, total)

        self.email_service.send_confirmation(user['email'], order_id)

        return OrderResult(success=True, order_id=order_id, total=total)
```

**Testing Strategy:**

1. **Unit Tests** (fast, isolated):
   - Test `validate_order` with various invalid inputs
   - Test `calculate_total` with premium/non-premium users
   - Test `process_order` with mocked dependencies

2. **Integration Tests** (slower, real dependencies):
   - Test with real database repositories
   - Test email service integration

3. **Contract Tests**:
   - Verify repository implementations match interfaces

